'use strict';

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=8.0.0"}] */

/* eslint n/no-unsupported-features/es-syntax: ["error", {"version": ">=8.0.0"}] */


// MODULES //

var Symbol = require( '@stdlib/symbol/ctor' );
var ArrayBuffer = require( '@stdlib/array/buffer' );
var Float64Array = require( '@stdlib/array/float64' );
var max = require( '@stdlib/math/base/special/max' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );
var isSafeInteger = require( '@stdlib/assert/is-safe-integer' ).isPrimitive;


// VARIABLES //

var MAX = 9007199254740991;
var prototype = Object.getPrototypeOf(Float64Array.prototype);
var tag = Object.getOwnPropertyDescriptor(prototype, Symbol.toStringTag).get;
var getLength = Object.getOwnPropertyDescriptor(prototype, 'length').get;
var buffer = Object.getOwnPropertyDescriptor(prototype, 'buffer').get;
var byteOffset = Object.getOwnPropertyDescriptor(prototype, 'byteOffset').get;
var byteLength = Object.getOwnPropertyDescriptor(ArrayBuffer.prototype, 'byteLength').get;


// FUNCTIONS //

/**
* Validates an exact primitive integer.
* @private
* @param {number} value - metadata
* @throws {RangeError} invalid integer
* @returns {integer} value
*/
function integer(value) {
	if (!isSafeInteger(value)) {
		throw new RangeError('invalid argument. Metadata must be exact primitive integers.');
	}
	return value;
}
/**
* Adds exact signed metadata before evaluating an indexed expression.
* @private
* @param {integer} x - first term
* @param {integer} y - second term
* @throws {RangeError} inexact sum
* @returns {integer} sum
*/
function sum(x, y) {
	if ((((y > 0) && (x > (MAX - y))) || ((y < 0) && (x < (-MAX - y))))) {
		throw new RangeError('invalid argument. Inexact indexed sum.');
	}
	return (x + y);
}
/**
* Computes a checked signed product.
* @private
* @param {NonNegativeInteger} n - count
* @param {integer} stride - signed stride
* @throws {RangeError} inexact product
* @returns {integer} product
*/
function product(n, stride) {
	var value;
	if (((n !== 0) && (abs(stride) > (MAX / n)))) {
		throw new RangeError('invalid argument. Inexact indexed product.');
	}
	value = (n * stride);
	return integer(value);
}
/**
* Computes a greatest common divisor.
* @private
* @param {PositiveInteger} x - first value
* @param {PositiveInteger} y - second value
* @returns {PositiveInteger} divisor
*/
function gcd(x, y) {
	var value;
	while ((y !== 0)) {
		value = (x % y);
		x = y;
		y = value;
	}
	return x;
}
/**
* Validates the full current intrinsic view and byte envelope.
* @private
* @param {TypedArray} x - intrinsic view
* @param {PositiveInteger} rows - rows
* @param {PositiveInteger} columns - columns
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - offset
* @param {string} dtype - expected intrinsic type
* @throws {TypeError} invalid brand or shared backing
* @throws {RangeError} invalid or colliding indexed view
* @returns {Object} byte envelope
*/
function view(x, rows, columns, r, c, o, dtype) {
	var data;
	var size;
	var dc;
	var dr;
	var hi;
	var lo;
	var g;
	if ((tag.call(x) !== dtype)) {
		throw new TypeError('invalid argument. Must provide the documented intrinsic typed array.');
	}
	data = buffer.call(x);
	byteLength.call(data);

	// Intrinsic ordinary-buffer brand, including current RAB extent.
	integer(r);
	integer(c);
	integer(o);
	if ((((rows > 1) && (r === 0)) || ((columns > 1) && (c === 0)))) {
		throw new RangeError('invalid argument. Active view strides cannot broadcast.');
	}
	if (((rows > 1) && (columns > 1))) {
		g = gcd(abs(r), abs(c));
		if ((((abs(c) / g) < rows) && ((abs(r) / g) < columns))) {
			throw new RangeError('invalid argument. The full view must be injective.');
		}
	}
	dr = product((rows - 1), r);
	dc = product((columns - 1), c);
	lo = sum(sum(o, min(dr, 0)), min(dc, 0));
	hi = sum(sum(o, max(dr, 0)), max(dc, 0));
	if (((lo < 0) || (hi >= getLength.call(x)))) {
		throw new RangeError('invalid argument. Indexed view exceeds the current intrinsic extent.');
	}
	size = (dtype === 'Float64Array') ? 8 : 4;
	return {
		'buffer': data,
		'first': sum(byteOffset.call(x), product(lo, size)),
		'last': sum(byteOffset.call(x), product(sum(hi, 1), size))
	};
}
/**
* Validates the scalar quartet before touching inactive arguments.
* @private
* @param {integer} M - rows
* @param {integer} N - columns
* @param {integer} KL - lower bandwidth
* @param {integer} KU - upper bandwidth
* @throws {RangeError} invalid scalar
* @returns {Object} derived geometry
*/
function scalars(M, N, KL, KU) {
	var values;
	var i;
	values = [
		M,
		N,
		KL,
		KU
	];
	for (i = 0; (i < values.length); i += 1) {
		integer(values[i]);
		if (((values[i] < 0) || (values[i] > 2147483647))) {
			throw new RangeError('invalid argument. Dimensions must be nonnegative signed32 integers.');
		}
	}
	return {
		'h': (((2 * KL) + KU) + 1),
		'kv': (KL + KU),
		'k': min(M, N),
		'empty': ((M === 0) || (N === 0))
	};
}


// MAIN //

/**
* Validates two active envelopes before any backend mutation.
* @private
* @param {Object} shape - derived scalar geometry
* @param {integer} N - columns
* @param {Float64Array} AB - band storage
* @param {integer} r - row stride
* @param {integer} c - column stride
* @param {integer} o - band offset
* @param {Int32Array} PIV - output step swaps
* @param {integer} sp - pivot stride
* @param {integer} op - pivot offset
* @throws {TypeError} invalid intrinsic storage
* @throws {RangeError} invalid view or overlap
* @returns {void}
*/
function validate(shape, N, AB, r, c, o, PIV, sp, op) {
	var a;
	var p;
	a = view(AB, shape.h, N, r, c, o, 'Float64Array');
	p = view(PIV, shape.k, 1, sp, 0, op, 'Int32Array');
	if ((((a.buffer === p.buffer) && (a.first < p.last)) && (p.first < a.last))) {
		throw new RangeError('invalid argument. Active indexed byte envelopes overlap.');
	}
}
validate.scalars = scalars;
validate.integer = integer;
module.exports = validate;
